<section class="card"><h2>Password policy</h2><form method="post" action="<?= $link('/users/password-policy') ?>"><?= $csrf ?><label>Minimum password length<input type="number" name="password_minimum" min="1" max="72" value="<?= $e($passwordMinimum) ?>" required></label><p class="help">Applies to new and changed account passwords. Existing passwords keep working. Passwords can contain at most 72 bytes.</p><button class="button secondary">Save password policy</button></form></section>
<div class="section-actions"><p class="muted">Staff and client accounts have separate access rules.</p><a class="button" href="<?= $link('/users/new') ?>">+ New user</a></div><div class="card table-card"><div class="table-scroll"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Audience</th><th>MFA</th><th>Status</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><a href="<?= $link('/users/'.$u['id'].'/edit') ?>"><?= $e($u['name']) ?></a></td><td><?= $e($u['username']) ?></td><td><?= $e(ucfirst($u['role'])) ?></td><td><?= $e(ucfirst($u['audience'])) ?></td><td><?= $u['mfa_enabled']?'Enabled':($u['require_mfa']?'Enrollment required':'Optional') ?></td><td><?= $u['active']?'Active':'Disabled' ?></td></tr><?php endforeach; ?></tbody></table></div></div>
